function slugify(s) { return s.toLowerCase().replace(/&/g,'and').replace(/\//g,' ').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''); }
function write(file, content) { fs.mkdirSync(path.dirname(file), {recursive:true}); if (!fs.existsSync(file)) fs.writeFileSync(file,content); }
